def build(store):
    """Заполнение таблиц equipment / org_units в хранилище (идемпотентно)."""
    for e in EQUIPMENT:
        eid, cls, name, maker, country, y0, y1, bands, pw, sens, sens_state, kind, dq, src = e
        store.x("""INSERT OR REPLACE INTO equipment(id,class,name,maker,country,year_from,year_to,bands,
                    power_w,sensitivity_dbm,sens_state,status_kind,data_quality,source,attrs)
                   VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                (eid, cls, name, maker, country, y0, y1, bands, pw, sens, sens_state, kind, dq, src,
                 json.dumps({"provenance": {"source": src, "recorded_at": time.strftime("%Y-%m-%d"),
                                            "verification_status": dq}}, ensure_ascii=False)))
    for u in ORG_UNITS:
        uid, parent, name, kind, ver, staff, fact, flags, sub = u
        store.x("""INSERT OR REPLACE INTO org_units(id,parent,name,kind,oshc_version,staff,fact,flags,subordination)
                   VALUES(?,?,?,?,?,?,?,?,?)""",
                (uid, parent, name, kind, ver, staff, fact, json.dumps(flags, ensure_ascii=False), sub))
    return {"equipment": len(EQUIPMENT), "org_units": len(ORG_UNITS)}


if __name__ == "__main__":
    from afina.server.core import Store
    path = sys.argv[1] if len(sys.argv) > 1 else "data/afina.db"
    st = Store(path)
    print(build(st))
